INSERT INTO blog_post_translations
  (post_id, locale, slug, title, excerpt, body_html, seo_title, seo_description)
VALUES (
  :post_id, 'uz', $x$xbox-hisobini-toldirish$x$,
  $x$Xbox hisobini Oʻzbekistondan qanday toʻldirish mumkin$x$,
  $x$Xbox’ni Oʻzbekistondan toʻldirish: Microsoft akkauntining mamlakati, mintaqani almashtirishdagi uch oy qoidasi, qaysi sovgʻa kartasini olish va uni qanday faollashtirish.$x$,
$x$<p>Xbox Microsoft akkauntingizda koʻrsatilgan mamlakatning sovgʻa kartasi bilan toʻldiriladi. Akkaunt mamlakatini aniqlang, shu mamlakat kartasini oling va kodni konsolda yoki Microsoft saytida faollashtiring.</p>
<h2>Asosiysi</h2>
<ul>
<li>Xbox kartasi faqat shu mamlakatdagi akkauntda ishlaydi. Microsoft karta mintaqasini oʻzgartirmaydi, hatto qoʻllab-quvvatlash orqali ham.</li>
<li>Microsoft akkaunti mamlakatini almashtirish mumkin, lekin uch oyda bir martadan koʻp emas.</li>
<li>Mamlakat almashtirilganda balansdagi pul koʻchmaydi. Avval uni sarflang.</li>
<li>Konsoldagi doʻkon mintaqasi akkaunt mamlakati bilan bir xil boʻlsin.</li>
<li>YuPay’da 21 mamlakatning Xbox kartalari bor, toʻlov soʻmda, Click, Payme yoki Uzum orqali. Yakuniy summa soʻmda toʻlovdan oldin koʻrinadi va aynan u yechiladi.</li>
</ul>
<h2>Akkaunt mamlakati va konsol mintaqasi</h2>
<p>Xbox’da koʻpincha adashtiriladigan ikki sozlama bor.</p>
<p><strong>Microsoft akkaunti mamlakati.</strong> Balans valyutasi va qaysi kartalar mos kelishi shunga bogʻliq. Uni Microsoft akkaunti profilidagi «Shaxsiy maʼlumotlar» boʻlimida koʻrish mumkin.</p>
<p><strong>Konsol mintaqasi.</strong> Bu konsolning oʻz sozlamasi: «Sozlamalar» → «Tizim» → «Til va joylashuv». U qaysi doʻkonni koʻrishingizni belgilaydi. Uni akkaunt mamlakati bilan bir xil qiling, aks holda doʻkon va balans har xil narsani koʻrsatadi.</p>
<p>Oʻzbekistondagi oʻyinchilar odatda boshqa mamlakat akkauntidan foydalanadi: AQSh, Turkiya, BAA, Polsha. Qaysi mamlakatni tanlash — oʻzingizga bogʻliq. Asosiysi, keyin akkauntni aynan shu mamlakat kartalari bilan toʻldirish.</p>
<h2>Xbox mintaqasini qanday almashtirish</h2>
<p>Akkaunt notoʻgʻri mamlakatga ochilgan boʻlsa, uni almashtirish mumkin. Microsoft qoidalari:</p>
<ol>
<li>Oxirgi uch oy ichida mamlakatni almashtirgan boʻlsangiz, uni yana oʻzgartirib boʻlmaydi.</li>
<li>Balansdagi pul yangi mintaqaga oʻtmaydi. Almashtirishdan oldin uni sarflang.</li>
<li>Baʼzi obunalar va xaridlar yangi mintaqada ishlamasligi mumkin. Buni oldindan tekshiring, ayniqsa faol obunangiz boʻlsa.</li>
<li>Akkaunt mamlakatini almashtirgach, «Til va joylashuv»da konsol mintaqasini ham oʻzgartiring.</li>
</ol>
<p>Uch oy qoidasi sababli bitta chegirma uchun mamlakatni almashtirmang. Mintaqani bir marta tanlang va uni toʻldirib boring.</p>
<h2>Qaysi kartani olish kerak</h2>
<p>Qoida bitta: akkaunt bilan bir xil mamlakat kartasi. AQSh kartasi turk akkauntida faollashmaydi va aksincha. Microsoft qoʻllab-quvvatlash xizmati kartani boshqa mintaqaga oʻtkaza olmaydi, shuning uchun notoʻgʻri xaridni keyin tuzatib boʻlmaydi.</p>
<p><a href="/uz/store/xbox">YuPay katalogida</a> mamlakat almashtirgichli bitta Xbox sahifasi bor. Masalan:</p>
<ul>
<li><a href="/uz/store/xbox?region=us">Xbox AQSh</a> — Amerika akkaunti uchun;</li>
<li><a href="/uz/store/xbox?region=tr">Xbox Turkiya</a> — turk akkaunti uchun;</li>
<li><a href="/uz/store/xbox?region=ae">Xbox BAA</a> — BAA akkaunti uchun;</li>
<li><a href="/uz/store/xbox?region=pl">Xbox Polsha</a> — polyak akkaunti uchun.</li>
</ul>
<p>Shuningdek, Buyuk Britaniya, Germaniya, Ispaniya, Braziliya, Meksika, Kanada, Yaponiya va boshqalar bor. «EU» kartasini faqat akkaunt mamlakati yevrohududda boʻlsa oling.</p>
<h2>Xbox kartasini qanday faollashtirish</h2>
<p>Toʻlovdan keyin kod buyurtma sahifasida koʻrinadi va pochtaga keladi. Uni ikki usulda faollashtirish mumkin.</p>
<p><strong>Konsolda:</strong></p>
<ol>
<li>Kerakli profilga kiring.</li>
<li>Microsoft Store’ni oching.</li>
<li>Menyu tugmasini bosing va «Kodni faollashtirish» (Redeem) bandini tanlang.</li>
<li>25 belgili kodni kiriting va tasdiqlang.</li>
</ol>
<p><strong>Saytda:</strong></p>
<ol>
<li>Microsoft saytidagi kodni faollashtirish sahifasini oching (microsoft.com/redeem).</li>
<li>Konsoldagi Microsoft akkauntining aynan oʻziga kiring.</li>
<li>Kodni kiriting va tasdiqlang.</li>
</ol>
<p>Pul akkaunt balansiga tushadi. Kod bir martalik: faollashtirilgandan keyin qayta ishlamaydi.</p>
<h2>Balansdan oʻyinlar va Game Pass</h2>
<p>Balans Microsoft Store’da sarflanadi: oʻyinlar, qoʻshimchalar, oʻyin ichidagi valyuta va Game Pass obunasiga. Xarid paytida akkaunt balansidan toʻlashni tanlang.</p>
<p>Kerakli summaga yetmasa, shu mamlakatning yana bir kartasini qoʻshing. Balanslar qoʻshiladi.</p>
<p>Grand Theft Auto VI 2026-yil 19-noyabrda chiqdi, jumladan Xbox Series X|S’da. Rockstar maʼlumotiga koʻra, Xbox kodlari mintaqaga bogʻlanmagan. Eng oddiy yoʻl — oʻyinni akkauntingiz Microsoft Store’ida balansdan sotib olish. Batafsil — <a href="/uz/blog/gta-6-ni-ozbekistonda-sotib-olish">GTA 6’ni Oʻzbekistonda sotib olish</a> qoʻllanmasida.</p>
<h2>Faollashtirishdagi xatolar</h2>
<p>Kod qabul qilinmasa, Xbox xato koʻrsatadi, koʻpincha «PUR-…» koʻrinishidagi kod bilan. Oddiy qilib aytganda, sabab uchta.</p>
<ul>
<li><strong>Boshqa akkaunt.</strong> Siz boshqa profilga yoki saytda boshqa Microsoft akkauntiga kirgansiz. Akkaunt pochtasini tekshiring.</li>
<li><strong>Boshqa mintaqa.</strong> Karta mamlakati akkaunt mamlakatiga mos emas. Bu koʻp uchraydigan sabab. Uni faqat akkaunt mamlakatini almashtirib, uch oy qoidasini hisobga olib tuzatish mumkin.</li>
<li><strong>Kod allaqachon faollashtirilgan yoki xato kiritilgan.</strong> Belgilarni solishtiring: harf va raqamlarni adashtirish oson. Akkauntning buyurtmalar tarixiga qarang: pul allaqachon balansda boʻlishi mumkin.</li>
</ul>
<p>Hammasi mos kelsa-yu, kod baribir oʻtmasa, buyurtma raqami bilan YuPay qoʻllab-quvvatlash xizmatiga yozing.</p>
<h2>Xulosa</h2>
<p>Microsoft akkauntingiz mamlakatini aniqlang, shu mamlakat kartasini oling va uni konsolda yoki saytda faollashtiring. Mintaqani kam almashtiring: uch oyda bir marta va faqat balans boʻsh boʻlganda.</p>
<p>Kerakli karta <a href="/uz/store/xbox">YuPay katalogidagi Xbox boʻlimida</a>. PlayStation’da mantiq oʻxshash, uni <a href="/uz/blog/ps-store-dan-oyin-sotib-olish">PS Store’dan oʻyin sotib olish</a> qoʻllanmasida koʻrib chiqqanmiz.</p>$x$,
  $x$Xbox’ni Oʻzbekistondan toʻldirish — kartalar va mintaqa$x$,
  $x$Xbox’ni Oʻzbekistondan toʻldirish: Microsoft akkauntingiz mamlakatining kartasi, mintaqani uch oyda bir marta almashtirish, kodni faollashtirish va PUR xatolari. Toʻlov soʻmda.$x$
);

